SELECT folder_id,material_id,topic,count() AS answers,countIf(result='wrong')/count() AS wrong_rate,countIf(rehab_active_before=false AND rehab_active_after=true) AS rehab_entries FROM knowledge_analytics.training_answers WHERE $__timeFilter(occurred_at) AND (${mode:sqlstring}='__all' OR mode=${mode:sqlstring}) AND (${algorithm:sqlstring}='__all' OR algorithm_version=${algorithm:sqlstring}) AND (${experiment:sqlstring}='__all' OR experiment_group=${experiment:sqlstring}) GROUP BY folder_id,material_id,topic HAVING answers>=3 ORDER BY wrong_rate DESC,answers DESC LIMIT 30
